import { memo, Fragment } from 'react';
import {
  TransferAssetInfoProps,
  TransferAssetInfoWrapperProps,
  AssetProps,
  TransferArrowProps,
  TokenValueProps,
  BankValueProps,
  transferAssetInfoSchema,
  transferAssetInfoWrapperSchema,
  assetSchema,
  transferArrowSchema,
  tokenValueSchema,
  bankValueSchema,
} from '~/entities/exchange/model/transfer-asset-info-schema';
import i18n from '~/shared/i18n/i18n';
import { validateProps } from '~/shared/lib/schema/zod-utils';

// 개별 컴포넌트 정의 및 내보내기 - 각각 독립적인 props 사용
export const TransferAssetInfoWrapper = memo(function TransferAssetInfoWrapper(props: TransferAssetInfoWrapperProps) {
  const { children, className = 'transfer-area' } = validateProps(
    transferAssetInfoWrapperSchema,
    props,
    'TransferAssetInfoWrapper',
  );

  return <div className={className}>{children}</div>;
});

export const TransferAssetInfoFromAsset = memo(function TransferAssetInfoFromAsset(props: AssetProps) {
  const { children, className = 'wallet-asset-info' } = validateProps(assetSchema, props, 'TransferAssetInfoFromAsset');
  return <div className={className}>{children}</div>;
});

export const TransferAssetInfoToAsset = memo(function TransferAssetInfoToAsset(props: AssetProps) {
  const { children, className = 'wallet-asset-info' } = validateProps(assetSchema, props, 'TransferAssetInfoToAsset');

  return <div className={className}>{children}</div>;
});

export const TransferAssetInfoArrow = memo(function TransferAssetInfoArrow(props: TransferArrowProps) {
  const { text, className = 'token-arr' } = validateProps(transferArrowSchema, props, 'TransferAssetInfoArrow');
  return <div className={className}>{text || i18n.t('transfer')}</div>;
});

export const TransferAssetInfoToken = memo(function TransferAssetInfoToken(props: TokenValueProps) {
  const { value, className = 'type' } = validateProps(tokenValueSchema, props, 'TransferAssetInfoToken');
  return <span className={className}>{value}</span>;
});

export const TransferAssetInfoBank = memo(function TransferAssetInfoBank(props: BankValueProps) {
  const { value, className = 'wallet-account SIB' } = validateProps(bankValueSchema, props, 'TransferAssetInfoBank');
  return (
    <Fragment>
      |<span className={className}>{value}</span>
    </Fragment>
  );
});

// 편의를 위한 조합 컴포넌트
export const TransferAssetInfo = memo(function TransferAssetInfo(props: TransferAssetInfoProps) {
  const {
    fromToken,
    fromBank = '',
    toToken,
    toBank = '',
  } = validateProps(transferAssetInfoSchema, props, 'TransferAssetInfo');

  return (
    <TransferAssetInfoWrapper>
      <TransferAssetInfoFromAsset>
        <TransferAssetInfoToken value={fromToken} />
        {fromBank && <TransferAssetInfoBank value={fromBank} />}
      </TransferAssetInfoFromAsset>
      <TransferAssetInfoArrow />
      <TransferAssetInfoToAsset>
        <TransferAssetInfoToken value={toToken} />
        {toBank && <TransferAssetInfoBank value={toBank} />}
      </TransferAssetInfoToAsset>
    </TransferAssetInfoWrapper>
  );
});
